#pragma once
#include <vector>
#include <span>
#include <string_view>
#include <initializer_list>
#include <cstddef>
#include <atomic>
#include <cassert>

namespace ws {

enum class NewLine {
    LF,   // \n
    CRLF  // \r\n
};

class IReadWriter;

class Buffer {
public:
    explicit Buffer(std::size_t size = 1000) noexcept;
    explicit Buffer(std::span<const std::byte> bytes) noexcept;
    explicit Buffer(std::initializer_list<std::byte> bytes) noexcept;
    explicit Buffer(std::string_view str) noexcept;

    std::size_t WritableSize() const noexcept;
    std::size_t ReadableSize() const noexcept;
    std::size_t PrependableSize() const noexcept;

    const std::byte* Peek() const noexcept;
    std::span<const std::byte> ReadableBytes() const noexcept;
    std::string_view ReadableString() const noexcept;

    void Append(std::span<const std::byte> bytes) noexcept;
    void Append(std::string_view str) noexcept;
    void Append(const Buffer& other) noexcept;
    std::span<std::byte> WritableBytes() noexcept;
    void HasWritten(std::size_t size) noexcept;

    void Retrieve(std::size_t size) noexcept;
    void RetrieveUntil(const std::byte* addr) noexcept;
    void RetrieveAll() noexcept;
    std::string RetrieveAllToString() noexcept;

    void Clear() noexcept;
    bool Empty() const noexcept;
    void EnsureWriteableSize(std::size_t size) noexcept;
    void MakeSpace(std::size_t size) noexcept;

private:
    std::vector<std::byte> buf_;
    std::atomic<std::size_t> read_pos_{0};
    std::atomic<std::size_t> write_pos_{0};

    auto ReadIter() const noexcept -> decltype(buf_.begin());
    auto WriteIter() const noexcept -> decltype(buf_.begin());
};

class IOBuffer : public Buffer {
public:
    void ReadFrom(io::IReadWriter& io);
    void WriteTo(io::IReadWriter& io);
};

inline Buffer::Buffer(std::size_t size) noexcept : buf_(size) {}

inline Buffer::Buffer(std::span<const std::byte> bytes) noexcept : buf_(bytes.begin(), bytes.end()) {}

inline Buffer::Buffer(std::initializer_list<std::byte> bytes) noexcept : buf_(bytes) {}

inline Buffer::Buffer(std::string_view str) noexcept {
    buf_.resize(str.size());
    std::memcpy(buf_.data(), str.data(), str.size());
}

inline std::size_t Buffer::WritableSize() const noexcept {
    return buf_.size() - write_pos_;
}

inline std::size_t Buffer::ReadableSize() const noexcept {
    return write_pos_ - read_pos_;
}

inline std::size_t Buffer::PrependableSize() const noexcept {
    return read_pos_;
}

inline const std::byte* Buffer::Peek() const noexcept {
    assert(!Empty());
    return &buf_[read_pos_];
}

inline std::span<const std::byte> Buffer::ReadableBytes() const noexcept {
    return {&buf_[read_pos_], ReadableSize()};
}

inline std::string_view Buffer::ReadableString() const noexcept {
    auto bytes = ReadableBytes();
    return {reinterpret_cast<const char*>(bytes.data()), bytes.size()};
}

inline void Buffer::Append(std::span<const std::byte> bytes) noexcept {
    EnsureWriteableSize(bytes.size());
    std::memcpy(WritableBytes().data(), bytes.data(), bytes.size());
    HasWritten(bytes.size());
}

inline void Buffer::Append(std::string_view str) noexcept {
    Append({reinterpret_cast<const std::byte*>(str.data()), str.size()});
}

inline void Buffer::Append(const Buffer& other) noexcept {
    Append(other.ReadableBytes());
}

inline std::span<std::byte> Buffer::WritableBytes() noexcept {
    return {WriteIter(), WritableSize()};
}

inline void Buffer::HasWritten(std::size_t size) noexcept {
    write_pos_ += size;
}

inline void Buffer::Retrieve(std::size_t size) noexcept {
    assert(size <= ReadableSize());
    read_pos_ += size;
}

inline void Buffer::RetrieveUntil(const std::byte* addr) noexcept {
    Retrieve(addr - Peek());
}

inline void Buffer::RetrieveAll() noexcept {
    read_pos_ = 0;
    write_pos_ = 0;
}

inline std::string Buffer::RetrieveAllToString() noexcept {
    auto bytes = ReadableBytes();
    std::string str(bytes.begin(), bytes.end());
    RetrieveAll();
    return str;
}

inline void Buffer::Clear() noexcept {
    buf_.clear();
    read_pos_ = 0;
    write_pos_ = 0;
}

inline bool Buffer::Empty() const noexcept {
    return ReadableSize() == 0;
}

inline void Buffer::EnsureWriteableSize(std::size_t size) noexcept {
    if (WritableSize() < size) {
        MakeSpace(size);
    }
}

inline void Buffer::MakeSpace(std::size_t size) noexcept {
    if (PrependableSize() + WritableSize() >= size) {
        std::memmove(buf_.data(), ReadIter(), ReadableSize());
        write_pos_ = ReadableSize();
        read_pos_ = 0;
    } else {
        buf_.resize(write_pos_ + size);
    }
}

inline auto Buffer::ReadIter() const noexcept -> decltype(buf_.begin()) {
    return buf_.begin() + read_pos_;
}

inline auto Buffer::WriteIter() const noexcept -> decltype(buf_.begin()) {
    return buf_.begin() + write_pos_;
}

inline void IOBuffer::ReadFrom(io::IReadWriter& io) {
    // Implementation depends on IReadWriter interface (not specified in design doc)
}

inline void IOBuffer::WriteTo(io::IReadWriter& io) {
    // Implementation depends on IReadWriter interface (not specified in design doc)
}

} // namespace ws

#include <iostream>
#include "Buffer.h"

int main() {
    ws::Buffer buf;
    buf.Append("Hello, ", ws::NewLine::LF);
    buf.Append("World!");
    std::string str = buf.RetrieveAllToString(); // "Hello,\nWorld!"
    std::cout << str << std::endl;
    return 0;
}
